import React, { useState, useEffect } from 'react';
import MediaList from '../components/MediaList';
import AnalyticsDashboard from '../components/AnalyticsDashboard';
import { mediaAPI, analyticsAPI } from '../services/api';

function Profile({ currentUser }) {
  const [userMedia, setUserMedia] = useState([]);
  const [analytics, setAnalytics] = useState({});

  useEffect(() => {
    loadUserMedia();
    loadAnalytics();
  }, [currentUser]);

  const loadUserMedia = async () => {
    try {
      const response = await mediaAPI.getAll();
      // Filter media by current user
      const filteredMedia = response.data.filter(media => media.userId === currentUser._id);
      setUserMedia(filteredMedia);
    } catch (error) {
      console.error('Error loading user media:', error);
    }
  };

  const loadAnalytics = async () => {
    try {
      const response = await analyticsAPI.get(currentUser._id);
      setAnalytics(response.data);
    } catch (error) {
      console.error('Error loading analytics:', error);
    }
  };

  return (
    <div className="profile">
      <h2>Profile</h2>
      <div className="profile-info">
        <h3>Profile Information</h3>
        <p><strong>Name:</strong> {currentUser.firstName} {currentUser.lastName}</p>
        <p><strong>Email:</strong> {currentUser.email}</p>
      </div>
      <AnalyticsDashboard analytics={analytics} />
      <MediaList media={userMedia} />
    </div>
  );
}

export default Profile;
